//! `docs/cli-reference.md` names nested subcommands by their full path
//! and its tables are well formed (#1031).
//!
//! The file is generated by `moagan-docgen cli`; the `cli-doc-sync`
//! workflow keeps it equal to the generator's output, so these checks
//! pin what the generator writes.

use std::path::Path;

fn reference() -> String {
    std::fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join("docs/cli-reference.md"))
        .expect("read docs/cli-reference.md")
}

/// Cells of one Markdown table row (`\|` is a literal pipe, not a separator).
fn cells(row: &str) -> usize {
    let unescaped = row.replace("\\|", "");
    unescaped.matches('|').count().saturating_sub(1)
}

#[test]
fn nested_subcommands_are_titled_and_used_with_their_parent() {
    let doc = reference();
    for (heading, usage) in [
        ("# probe top-p", "**Usage:** `moagan probe top-p [OPTIONS]`"),
        ("# audit proxy", "**Usage:** `moagan audit proxy [OPTIONS]`"),
        (
            "# discover merge",
            "**Usage:** `moagan discover merge <RUN_ID>... [OPTIONS]`",
        ),
        (
            "# telemetry alerts list",
            "**Usage:** `moagan telemetry alerts list [OPTIONS]`",
        ),
    ] {
        assert!(
            doc.lines().any(|l| l == heading),
            "missing heading {heading:?}"
        );
        assert!(doc.contains(usage), "missing usage {usage:?}");
    }
    for bare in ["# top-p", "# proxy", "# merge", "# verify"] {
        assert!(
            !doc.lines().any(|l| l == bare),
            "nested subcommand titled without its parent: {bare:?}"
        );
    }
    assert!(
        !doc.contains("**Usage:** `moagan top-p"),
        "usage without the parent"
    );
}

#[test]
fn every_section_heading_is_unique() {
    let doc = reference();
    let mut seen = std::collections::BTreeSet::new();
    for heading in doc.lines().filter(|l| l.starts_with("# ")) {
        assert!(seen.insert(heading), "duplicate heading {heading:?}");
    }
}

#[test]
fn every_table_row_has_as_many_cells_as_its_header() {
    let doc = reference();
    let lines: Vec<&str> = doc.lines().collect();
    let mut tables = 0;
    let mut i = 0;
    while i + 1 < lines.len() {
        if lines[i].starts_with('|') && lines[i + 1].starts_with("|---") {
            tables += 1;
            let want = cells(lines[i]);
            let mut j = i + 2;
            while j < lines.len() && lines[j].starts_with('|') {
                assert_eq!(
                    cells(lines[j]),
                    want,
                    "line {}: {:?} under header {:?}",
                    j + 1,
                    lines[j],
                    lines[i]
                );
                j += 1;
            }
            i = j;
        } else {
            i += 1;
        }
    }
    assert!(tables > 10, "only {tables} tables found");
}
